function drawFlower(f) {
  const sway = Math.sin(time * 1.05 + f.phase) * 3.4;
  const stemTop = -38;

  ctx.save();
  ctx.translate(f.x, f.y);
  ctx.scale(f.s, f.s);

  ctx.strokeStyle = 'rgba(126, 214, 174, 0.5)';
  ctx.lineWidth = 2.2;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.quadraticCurveTo(sway * 0.4, -18, sway, stemTop);
  ctx.stroke();

  // leaves
  ctx.fillStyle = 'rgba(106, 196, 158, 0.45)';
  ctx.beginPath();
  ctx.ellipse(-5, -16, 7, 3.2, -0.5, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(5, -24, 7, 3.2, 0.5, 0, TAU);
  ctx.fill();

  const t = clamp(f.bloom, 0, 1);

  if (t <= 0.01) {
    ctx.fillStyle = 'rgba(150, 200, 170, 0.65)';
    ctx.beginPath();
    ctx.ellipse(sway, stemTop, 3, 5.4, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
    return;
  }

  const e = easeOutBack(t);
  ctx.translate(sway, stemTop);
  ctx.scale(e, e);

