1017:   function worldFromEvent(e) {
1018:     const rect = canvas.getBoundingClientRect();
1019:     const scale = Math.min(rect.width / W, rect.height / H);
1020:     const ox = (rect.width - W * scale) / 2;
1021:     const oy = (rect.height - H * scale) / 2;
1022:     return {
1023:       x: clamp((e.clientX - rect.left - ox) / scale, 0, W),
1024:       y: clamp((e.clientY - rect.top - oy) / scale, 0, H)
1025:     };
1026:   }
