1028:   function onPointerMove(e) {
1029:     const p = worldFromEvent(e);
1030:     pointer.x = p.x;
1031:     pointer.y = p.y;
1032:     pointer.inside = true;
1033:     pointer.type = e.pointerType || 'mouse';
1034:     if (e.pointerType === 'touch') {
1035:       stage.classList.add('is-touch');
1036:       pointer.active = true;
1037:     } else if (e.pointerType === 'pen' || (e.buttons & 1) || !pointer.touch) {
1038:       pointer.active = true;
1039:     }
1040:     if (pointer.type === 'mouse') pointer.active = true;
1041:   }
