1045:     canvas.setPointerCapture && canvas.setPointerCapture(e.pointerId);
1046:     if (e.pointerType === 'touch') pointer.touch = true;
1047:     onPointerMove(e);
1048:     if (state === 'title') sound.init();
1049:   });
1050:   canvas.addEventListener('pointerenter', (e) => {
1051:     pointer.inside = true;
1052:     if (e.pointerType === 'mouse') pointer.active = true;
1053:   });
