1059:   // ---------- update ----------
1060:   function updateLumi(dt, mode) {
1061:     let tx;
1062:     let ty;
1063: 
1064:     if (mode === 'idle') {
1065:       tx = 1012 + Math.cos(time * 0.6) * 16;
1066:       ty = 322 + Math.sin(time * 0.85) * 12;
1067:     } else if (mode === 'hold') {
1068:       tx = W * 0.5 + Math.cos(time * 0.5) * 10;
1069:       ty = H * 0.62 + Math.sin(time * 0.8) * 8;
1070:     } else if (lumi.stun > 0) {
1071:       tx = lumi.x;
1072:       ty = lumi.y;
1073:     } else {
1074:       const k = keyVector();
1075:       if (k.x || k.y) {
1076:         const len = Math.hypot(k.x, k.y) || 1;
1077:         const speed = 470;
1078:         lumi.vx = lerp(lumi.vx, (k.x / len) * speed, Math.min(1, dt * 9));
1079:         lumi.vy = lerp(lumi.vy, (k.y / len) * speed, Math.min(1, dt * 9));
1080:         integrateLumi(dt);
1081:         return;
1082:       }
1083:       tx = pointer.active ? pointer.x : W / 2;
1084:       ty = pointer.active ? pointer.y : H * 0.58;
1085:     }
1086: 
1087:     if (lumi.stun > 0) {
1088:       lumi.stun -= dt;
1089:       lumi.vx *= Math.pow(0.02, dt);
1090:       lumi.vy *= Math.pow(0.02, dt);
1091:     } else {
1092:       const omega = 9.2;
1093:       const dx = tx - lumi.x;
1094:       const dy = ty - lumi.y;
1095:       lumi.vx += (dx * omega * omega - 2 * omega * lumi.vx) * dt;
1096:       lumi.vy += (dy * omega * omega - 2 * omega * lumi.vy) * dt;
1097:       if (Math.hypot(dx, dy) < 4) {
1098:         lumi.vx *= Math.pow(0.001, dt);
1099:         lumi.vy *= Math.pow(0.001, dt);
1100:       }
1101:     }
1102: 
1103:     integrateLumi(dt);
1104:   }
1105: 
1106:   function integrateLumi(dt) {
1107:     const sp = Math.hypot(lumi.vx, lumi.vy);
1108:     const maxSp = 720;
1109:     if (sp > maxSp) {
1110:       lumi.vx = (lumi.vx / sp) * maxSp;
1111:       lumi.vy = (lumi.vy / sp) * maxSp;
1112:     }
1113:     lumi.x += lumi.vx * dt;
1114:     lumi.y += lumi.vy * dt;
1115: 
1116:     const padX = 34;
1117:     const padTop = 64;
1118:     const padBottom = 40;
1119:     if (lumi.x < padX) { lumi.x = padX; lumi.vx = Math.abs(lumi.vx) * 0.25; }
1120:     if (lumi.x > W - padX) { lumi.x = W - padX; lumi.vx = -Math.abs(lumi.vx) * 0.25; }
1121:     if (lumi.y < padTop) { lumi.y = padTop; lumi.vy = Math.abs(lumi.vy) * 0.25; }
1122:     if (lumi.y > H - padBottom) { lumi.y = H - padBottom; lumi.vy = -Math.abs(lumi.vy) * 0.25; }
1123: 
1124:     lumi.tilt = clamp(lumi.vx / 2600, -0.2, 0.2);
1125: 
1126:     const speed = Math.hypot(lumi.vx, lumi.vy);
1127:     if (speed > 130) {
1128:       lumi.trail.push({ x: lumi.x, y: lumi.y, life: 0.32, r: lumi.r * rand(0.5, 0.85) });
1129:       if (lumi.trail.length > 20) lumi.trail.shift();
1130:     }
1131: 
1132:     lumi.nextBlink -= dt;
1133:     if (lumi.nextBlink <= 0 && lumi.blink <= 0) {
1134:       lumi.blink = 0.16;
1135:       lumi.nextBlink = rand(2.4, 5.4);
1136:     }
1137:     if (lumi.blink > 0) lumi.blink -= dt;
1138:   }
1139: 
1140:   function updateSeeds(dt) {
1141:     for (let i = seeds.length - 1; i >= 0; i--) {
1142:       const s = seeds[i];
1143:       s.phase += dt * (s.spin || 1);
1144: 
1145:       if (s.kind === 'star') {
1146:         s.life -= dt;
1147:         s.x += Math.cos(time * 0.9 + s.phase) * 9 * dt;
1148:         s.y += Math.sin(time * 1.2 + s.phase) * 9 * dt;
1149:         if (s.life <= 0) { seeds.splice(i, 1); continue; }
1150:       } else {
1151:         s.y += s.vy * dt;
1152:         s.x += Math.sin(time * 1.5 + s.phase) * 16 * dt;
1153:         if (s.y > H + 70) { seeds.splice(i, 1); continue; }
1154:         const dx = lumi.x - s.x;
1155:         const dy = lumi.y - s.y;
1156:         const d = Math.hypot(dx, dy) || 1;
1157:         if (d < 120) {
1158:           s.x += (dx / d) * 90 * dt;
1159:           s.y += (dy / d) * 90 * dt;
1160:         }
1161:       }
1162: 
1163:       const dx = lumi.x - s.x;
1164:       const dy = lumi.y - s.y;
1165:       const rr = lumi.r + s.r + 4;
1166:       if (dx * dx + dy * dy < rr * rr) {
1167:         seeds.splice(i, 1);
1168:         if (s.kind === 'star') collectStar(s);
1169:         else collectSeed(s);
1170:       }
1171:     }
1172:   }
1173: 
1174:   function updateFogs(dt) {
1175:     for (let i = 0; i < fogs.length; i++) {
1176:       const f = fogs[i];
1177:       f.phase += dt;
1178: 
1179:       if (f.flee > 0) {
1180:         f.flee -= dt;
1181:         const k = Math.max(0, f.flee / 2.6);
1182:         f.x += f.dirx * (90 + 270 * k) * dt;
1183:         f.y += f.diry * (90 + 270 * k) * dt;
1184:       } else {
1185:         for (let j = 0; j < fogs.length; j++) {
1186:           if (j === i) continue;
1187:           const o = fogs[j];
1188:           const dx = f.x - o.x;
1189:           const dy = f.y - o.y;
1190:           const d = Math.hypot(dx, dy) || 1;
1191:           const min = f.r + o.r;
1192:           if (d < min) {
1193:             f.x += (dx / d) * (min - d) * 0.5;
1194:             f.y += (dy / d) * (min - d) * 0.5;
1195:           }
1196:         }
1197: 
1198:         const desired = Math.atan2(lumi.y - f.y, lumi.x - f.x) + Math.sin(time * 1.3 + f.phase) * 0.6;
1199:         const speed = level.fogSpeed;
1200:         f.vx = lerp(f.vx, Math.cos(desired) * speed, Math.min(1, dt * 1.7));
1201:         f.vy = lerp(f.vy, Math.sin(desired) * speed, Math.min(1, dt * 1.7));
1202:         f.x += f.vx * dt;
1203:         f.y += f.vy * dt;
1204:       }
1205: 
1206:       if (f.x < 66) { f.x = 66; f.vx = Math.abs(f.vx) * 0.5; }
1207:       if (f.x > W - 66) { f.x = W - 66; f.vx = -Math.abs(f.vx) * 0.5; }
1208:       if (f.y < 120) { f.y = 120; f.vy = Math.abs(f.vy) * 0.5; }
1209:       if (f.y > H - 80) { f.y = H - 80; f.vy = -Math.abs(f.vy) * 0.5; }
1210: 
1211:       f.nextBlink -= dt;
1212:       if (f.nextBlink <= 0) {
1213:         f.blink = 0.18;
1214:         f.nextBlink = rand(2.5, 6);
1215:       }
1216:       if (f.blink > 0) f.blink -= dt;
1217: 
1218:       const dx = lumi.x - f.x;
1219:       const dy = lumi.y - f.y;
1220:       const rr = lumi.r + f.r * 0.74;
1221:       if (dx * dx + dy * dy < rr * rr) hitFog(f);
1222:     }
1223:   }
1224: 
1225:   function updateParticles(dt) {
1226:     for (let i = particles.length - 1; i >= 0; i--) {
1227:       const p = particles[i];
1228:       p.life -= dt;
1229:       if (p.life <= 0) { particles.splice(i, 1); continue; }
1230:       p.x += p.vx * dt;
1231:       p.y += p.vy * dt;
1232:       p.vy += p.gravity * dt;
1233:       p.vx *= Math.pow(0.4, dt * p.drag);
1234:       p.vy *= Math.pow(0.4, dt * p.drag);
1235:     }
1236:     for (let i = rings.length - 1; i >= 0; i--) {
1237:       const r = rings[i];
1238:       r.life -= dt;
1239:       r.r += r.vr * dt;
1240:       if (r.life <= 0) rings.splice(i, 1);
1241:     }
1242:     for (let i = floaters.length - 1; i >= 0; i--) {
1243:       const f = floaters[i];
1244:       f.life -= dt;
1245:       f.y -= 34 * dt;
1246:       if (f.life <= 0) floaters.splice(i, 1);
1247:     }
1248:     for (let i = lumi.trail.length - 1; i >= 0; i--) {
1249:       lumi.trail[i].life -= dt;
1250:       if (lumi.trail[i].life <= 0) lumi.trail.splice(i, 1);
1251:     }
1252:   }
