1254:   function update(dt) {
1255:     // world ambience runs in every state
1256:     for (const f of fireflies) {
1257:       f.x += Math.cos(time * f.sp + f.phase) * f.amp * dt * 0.6 + f.drift * dt;
1258:       f.y += Math.sin(time * f.sp * 1.3 + f.phase * 2) * f.amp * 0.45 * dt;
1259:       if (f.x < -30) f.x = W + 30;
1260:       if (f.x > W + 30) f.x = -30;
1261:       if (f.y < 130) f.y = 130;
1262:       if (f.y > H - 60) f.y = H - 60;
1263:     }
1264:     for (const f of flowers) {
1265:       if (f.bloomed && f.bloom < 1) f.bloom = Math.min(1, f.bloom + dt * 1.5);
1266:     }
1267:     for (const d of decoSeeds) {
1268:       d.y += d.vy * dt;
1269:       d.phase += dt;
1270:       if (d.y < 90) { d.y = 560; d.x = 700 + Math.random() * 240; }
1271:     }
1272: 
1273:     updateParticles(dt);
1274:     if (shake > 0) shake = Math.max(0, shake - dt * 3.4);
1275:     if (invuln > 0) invuln = Math.max(0, invuln - dt);
1276: 
1277:     if (comboTimer > 0) {
1278:       comboTimer -= dt;
1279:       if (comboTimer <= 0) {
1280:         combo = 0;
1281:         mult = 1;
1282:         updateComboUI();
1283:       }
1284:     }
1285: 
1286:     if (state === 'playing') {
1287:       updateLumi(dt, 'play');
1288: 
1289:       light -= level.drain * dt;
1290:       if (light <= 0) {
1291:         light = 0;
1292:         updateHud();
1293:         if (state === 'playing') lightOut();
1294:       }
1295: 
1296:       spawnTimer -= dt;
1297:       const alive = seeds.filter((s) => s.kind === 'seed').length;
1298:       if (spawnTimer <= 0 && alive < 4 + (levelIndex > 2 ? 1 : 0)) {
1299:         spawnSeed(false);
1300:         spawnTimer = level.spawnEvery * rand(0.78, 1.2);
1301:       }
1302: 
1303:       updateSeeds(dt);
1304:       updateFogs(dt);
1305:     } else if (state === 'title') {
1306:       updateLumi(dt, 'idle');
1307:     } else if (state === 'intro') {
1308:       updateLumi(dt, 'hold');
1309:     } else {
1310:       updateLumi(dt, 'hold');
1311:     }
1312: 
1313:     updateHud();
1314:   }
